import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise 32 small equal circles on a grid."""
    if start is not None:
        return np.asarray(start, dtype=float)
    k = int(np.ceil(np.sqrt(32)))
    pts = [((i + 0.5) / k, (j + 0.5) / k) for j in range(k) for i in range(k)][:32]
    return np.array([[x, y, 0.02] for x, y in pts])

import numpy as np
import time


def _feasible(circles, eps=1e-9):
    n = circles.shape[0]
    x = circles[:, 0]; y = circles[:, 1]; r = circles[:, 2]
    if np.any(r <= 0):
        return False
    if np.any(x - r < -eps) or np.any(x + r > 1 + eps):
        return False
    if np.any(y - r < -eps) or np.any(y + r > 1 + eps):
        return False
    for i in range(n):
        for j in range(i + 1, n):
            dx = x[i] - x[j]; dy = y[i] - y[j]
            d = (dx*dx + dy*dy) ** 0.5
            if d < r[i] + r[j] - eps:
                return False
    return True


def _shrink(circles, factor=1e-7):
    c = circles.copy()
    c[:, 2] *= (1.0 - factor)
    return c


def _score(circles):
    return float(np.sum(circles[:, 2]))


def _project(circles, iters=50):
    c = circles.copy()
    n = c.shape[0]
    for _ in range(iters):
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        r_new = np.minimum(r, np.minimum(np.minimum(x, 1 - x), np.minimum(y, 1 - y)))
        c[:, 2] = np.maximum(r_new, 1e-6)
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        moved = False
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[j] - x[i]; dy = y[j] - y[i]
                d = (dx*dx + dy*dy) ** 0.5
                need = r[i] + r[j]
                if d < need - 1e-12:
                    moved = True
                    if d < 1e-12:
                        dx, dy, d = 1e-3, 0.0, 1e-3
                    push = (need - d) * 0.5 + 1e-9
                    ux, uy = dx / d, dy / d
                    c[i, 0] -= ux * push
                    c[i, 1] -= uy * push
                    c[j, 0] += ux * push
                    c[j, 1] += uy * push
        if not moved:
            break
    return c


def _grow(circles, steps=400, dt=0.01):
    c = circles.copy()
    best = c.copy()
    best_s = _score(c)
    for s in range(steps):
        c[:, 2] *= (1.0 + dt)
        c = _project(c, iters=30)
        c[:, 2] = np.minimum(c[:, 2],
                             np.minimum(np.minimum(c[:, 0], 1 - c[:, 0]),
                                        np.minimum(c[:, 1], 1 - c[:, 1])))
        sc = _score(c)
        if sc > best_s and _feasible(c, eps=1e-7):
            best_s = sc
            best = c.copy()
    return best


def _initial_grid():
    n = 32
    pts = []
    rows = 6
    for row in range(rows):
        cols = 6 if row % 2 == 0 else 5
        for col in range(cols):
            if len(pts) >= n:
                break
            x = (col + 0.5 + (0.5 if row % 2 else 0.0)) / 6.0
            y = (row + 0.5) / rows
            pts.append((x, y))
        if len(pts) >= n:
            break
    while len(pts) < n:
        pts.append((0.5, 0.5))
    pts = pts[:n]
    r0 = 0.03
    return np.array([[x, y, r0] for x, y in pts])


def _smooth(circles, iters=60):
    """Pull each circle to increase min clearance; relax positions then regrow."""
    c = circles.copy()
    n = c.shape[0]
    for _ in range(iters):
        x = c[:, 0]; y = c[:, 1]; r = c[:, 2]
        fx = np.zeros(n); fy = np.zeros(n)
        for i in range(n):
            for j in range(i + 1, n):
                dx = x[j] - x[i]; dy = y[j] - y[i]
                d2 = dx*dx + dy*dy + 1e-12
                d = d2 ** 0.5
                need = r[i] + r[j]
                if d < need * 1.5:
                    overlap = need - d
                    if overlap > 0:
                        w = overlap / d
                        fx[i] -= dx * w; fy[i] -= dy * w
                        fx[j] += dx * w; fy[j] += dy * w
        # wall attraction to keep inside with radius margin
        for i in range(n):
            ri = r[i]
            if x[i] - ri < 0: fx[i] += (ri - x[i])
            if x[i] + ri > 1: fx[i] -= (x[i] + ri - 1)
            if y[i] - ri < 0: fy[i] += (ri - y[i])
            if y[i] + ri > 1: fy[i] -= (y[i] + ri - 1)
        c[:, 0] += 0.5 * fx
        c[:, 1] += 0.5 * fy
        c[:, 0] = np.clip(c[:, 0], 0.0, 1.0)
        c[:, 1] = np.clip(c[:, 1], 0.0, 1.0)
    return c


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.2

    if start is not None:
        start = np.asarray(start, dtype=float).copy()
        if start.shape != (32, 3):
            start = _initial_grid()
    else:
        start = _initial_grid()

    cand = _project(start.copy(), iters=100)
    cand = _shrink(cand, 1e-6)
    if not _feasible(cand, eps=1e-9):
        cand = _initial_grid()
        cand = _shrink(_project(cand, iters=200), 1e-5)

    best = cand.copy()
    best_s = _score(best)

    attempts = [0.004, 0.008, 0.015, 0.003, 0.006, 0.012, 0.02]
    ai = 0
    while time.process_time() < deadline:
        dt = attempts[ai % len(attempts)]
        ai += 1
        trial = best.copy()
        # smooth relax to escape jammed configs
        trial = _smooth(trial, iters=30)
        noise = (np.random.rand(32, 2) - 0.5) * 0.008
        trial[:, :2] = np.clip(trial[:, :2] + noise, 0.0, 1.0)
        trial = _project(trial, iters=40)
        trial = _grow(trial, steps=80, dt=dt)
        trial = _project(trial, iters=60)
        trial = _smooth(trial, iters=20)
        trial = _project(trial, iters=40)
        trial = _shrink(trial, 1e-7)
        if _feasible(trial, eps=1e-9):
            sc = _score(trial)
            if sc > best_s:
                best_s = sc
                best = trial.copy()

    best = _shrink(best, 1e-6)
    for _ in range(20):
        if _feasible(best, eps=1e-9):
            break
        best = _shrink(best, 1e-4)
    return best
